/* KIT vanilla — tabs: 44px targets, visible focus, arrow-key support via tabs.js. */
.kit-tabs { display: flex; flex-direction: column; gap: var(--kit-space-base, 12px); }
.kit-tabs > [role="tablist"] {
  display: flex;
  gap: 4px;
  border-bottom: 1px solid var(--border);
  overflow-x: auto;
}
.kit-tabs [role="tab"] {
  appearance: none;
  border: none;
  background: none;
  min-height: var(--kit-control-height, 44px);
  padding: 0 var(--kit-space-base, 12px);
  font: inherit;
  font-size: var(--kit-body-size, 15px);
  font-weight: 600;
  color: var(--muted-foreground);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  white-space: nowrap;
  transition: color var(--kit-fast, 120ms) var(--kit-ease, ease-out);
}
.kit-tabs [role="tab"]:hover { color: var(--foreground); }
.kit-tabs [role="tab"][aria-selected="true"] {
  color: var(--foreground);
  border-bottom-color: var(--primary);
}
.kit-tabs [role="tab"]:focus-visible { outline: 2px solid var(--ring); outline-offset: -2px; }
.kit-tabs [role="tabpanel"] {
  font-size: var(--kit-body-size, 15px);
  line-height: var(--kit-leading, 1.5);
}
.kit-tabs [role="tabpanel"][hidden] { display: none; }

@media (prefers-reduced-motion: reduce) {
  .kit-tabs [role="tab"] { transition-duration: 0.01ms; }
}

/* KIT vanilla — tabs behavior: click + Left/Right/Home/End keys. */
(function () {
  function activate(tabs, tab) {
    var list = tabs.querySelectorAll('[role="tab"]')
    list.forEach(function (t) {
      var selected = t === tab
      t.setAttribute("aria-selected", selected ? "true" : "false")
      t.tabIndex = selected ? 0 : -1
      var panel = document.getElementById(t.getAttribute("aria-controls"))
      if (panel) panel.hidden = !selected
    })
    tab.focus()
  }

  document.addEventListener("click", function (event) {
    var tab = event.target.closest('[data-kit-tabs] [role="tab"]')
    if (tab) activate(tab.closest("[data-kit-tabs]"), tab)
  })

  document.addEventListener("keydown", function (event) {
    var tab = event.target.closest('[data-kit-tabs] [role="tab"]')
    if (!tab) return
    var tabs = tab.closest("[data-kit-tabs]")
    var list = Array.prototype.slice.call(tabs.querySelectorAll('[role="tab"]'))
    var index = list.indexOf(tab)
    var next = null
    if (event.key === "ArrowRight") next = list[(index + 1) % list.length]
    if (event.key === "ArrowLeft") next = list[(index - 1 + list.length) % list.length]
    if (event.key === "Home") next = list[0]
    if (event.key === "End") next = list[list.length - 1]
    if (next) {
      event.preventDefault()
      activate(tabs, next)
    }
  })
})();
